INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3200, 'hardship', '/ˈhɑːrdʃɪp/', 'noun', '{"zh-TW":["艱難；困苦"],"en":["severe suffering or difficulty"]}', NULL, 'endure/face/suffer hardship', '[{"en":"Many families endured hardship during the recession.","zh-TW":"許多家庭在經濟衰退期間忍受了困苦。"},{"en":"Financial hardship forced them to relocate.","zh-TW":"經濟困難迫使他們搬遷。"}]', '{"noun":"hardship","adjective":"hard"}', NULL, 3, 3200, NULL),
(3201, 'hardware', '/ˈhɑːrdwɛər/', 'noun', '{"zh-TW":["硬體"],"en":["the physical components of a computer system"]}', NULL, 'computer hardware / upgrade hardware', '[{"en":"The company replaced its outdated hardware with new machines.","zh-TW":"公司用新機器替換了過時的硬體。"},{"en":"Hardware problems can cause system crashes.","zh-TW":"硬體問題可能導致系統崩潰。"}]', NULL, NULL, 3, 3201, NULL),
(3202, 'harm', '/hɑːrm/', 'noun, verb', '{"zh-TW":["傷害；損害"],"en":["physical or psychological injury or damage"]}', NULL, 'do harm / cause harm / come to harm', '[{"en":"Smoking can cause serious harm to your health.","zh-TW":"吸菸會對你的健康造成嚴重傷害。"},{"en":"The chemicals may harm the environment.","zh-TW":"這些化學物質可能會損害環境。"}]', '{"noun":"harm","adjective":"harmful, harmless","verb":"harm"}', NULL, 1, 3202, NULL),
(3203, 'harmonization', '/ˌhɑːrmənaɪˈzeɪʃən/', 'noun', '{"zh-TW":["調和；協調統一"],"en":["the process of standardizing rules or practices across different regions or entities"]}', NULL, 'harmonization of regulations / tax harmonization', '[{"en":"Harmonization of accounting standards simplifies global financial reporting.","zh-TW":"會計準則的調和簡化了全球財務報告。"},{"en":"Trade harmonization between the two countries reduced customs complexity.","zh-TW":"兩國之間的貿易調和降低了海關複雜性。"}]', '{"verb":"harmonize"}', NULL, 5, 3203, 790),
(3204, 'harmonize', '/ˈhɑːrmənaɪz/', 'verb', '{"zh-TW":["協調；使協調一致"],"en":["to bring into agreement or alignment"]}', NULL, 'harmonize regulations / harmonize reporting standards', '[{"en":"The two subsidiaries harmonized their accounting policies after the merger.","zh-TW":"合並後，兩家子公司協調了各自的會計政策。"},{"en":"International bodies work to harmonize global trade regulations.","zh-TW":"國際機構致力於協調全球貿易法規。"}]', '{"noun":"harmonization","adjective":"harmonized"}', NULL, 3, 3204, 691),
(3205, 'harmony', '/ˈhɑːrməni/', 'noun', '{"zh-TW":["和諧；融洽"],"en":["a state of peaceful agreement and cooperation"]}', NULL, 'in harmony with / live in harmony', '[{"en":"The team works in harmony to achieve goals.","zh-TW":"團隊和諧合作以達成目標。"},{"en":"We must live in harmony with nature.","zh-TW":"我們必須與自然和諧共處。"}]', '{"noun":"harmony","adjective":"harmonious","verb":"harmonize"}', NULL, 3, 3205, NULL),
(3206, 'harvest', '/ˈhɑːrvɪst/', 'noun, verb', '{"zh-TW":["收穫；收成"],"en":["the process of gathering crops","to collect crops from the fields"]}', NULL, 'harvest season / harvest crops', '[{"en":"The harvest was abundant this year.","zh-TW":"今年的收成很豐富。"},{"en":"Farmers harvest wheat in late summer.","zh-TW":"農民在夏末收割小麥。"}]', '{"noun":"harvest, harvester","verb":"harvest"}', NULL, 3, 3206, NULL),
(3207, 'hash function', '/hæʃ ˈfʌŋkʃən/', 'noun', '{"zh-TW":["雜湊函數"],"en":["a function mapping data of arbitrary size to fixed-size values"]}', NULL, 'apply a hash function / cryptographic hash function / hash function collision', '[{"en":"Hash functions ensure data integrity in digital signatures.","zh-TW":"雜湊函數確保數字簽名中的數據完整性。"},{"en":"SHA-256 is a widely used cryptographic hash function.","zh-TW":"SHA-256是廣泛使用的密碼學雜湊函數。"}]', NULL, NULL, 5, 3207, NULL),
(3208, 'hasten', '/ˈheɪsn/', 'verb', '{"zh-TW":["加速；催促"],"en":["to make something happen sooner or more quickly"]}', NULL, 'hasten the process / hasten to add', '[{"en":"The treatment hastened her recovery.","zh-TW":"這項治療加速了她的康復。"},{"en":"He hastened to assure them that everything was fine.","zh-TW":"他趕忙向他們保證一切都好。"}]', '{"noun":"haste","verb":"hasten","adjective":"hasty","adverb":"hastily"}', NULL, 2, 3208, NULL),
(3209, 'hat trick', '/''hæt trɪk/', 'noun', '{"zh-TW":["帽子戲法；三連得分"],"en":["three successes of the same kind, especially in sports where one player scores three goals in one game"]}', NULL, 'score a hat trick / perform a hat trick / celebrate a hat trick', '[{"en":"The striker scored a hat trick in the final, leading his team to victory.","zh-TW":"這位前鋒在決賽中打入帽子戲法，帶領球隊獲勝。"},{"en":"A hat trick in baseball refers to striking out three times in a single game.","zh-TW":"在棒球中，帽子戲法是指在一場比賽中三次被三振出局。"}]', NULL, NULL, 3, 3209, NULL),
(3210, 'hate', '/heɪt/', 'verb', '{"zh-TW":["討厭；憎恨"],"en":["to dislike very strongly"]}', NULL, 'hate to say / hate speech', '[{"en":"I hate to say this, but we need to cut the budget.","zh-TW":"我不想這麼說，但我們需要削減預算。"},{"en":"The company has a zero-tolerance policy on hate speech.","zh-TW":"公司對仇恨言論零容忍。"}]', '{"verb":"hate","noun":"hate","noun2":"hatred","adjective":"hateful"}', NULL, 1, 3210, NULL),
(3211, 'hazard', '/ˈhæzərd/', 'noun, verb', '{"zh-TW":["危險；危害","冒險"],"en":["a danger or risk","to risk or venture something"]}', NULL, 'health/safety hazard / hazard a guess', '[{"en":"Wet floors are a safety hazard.","zh-TW":"濕滑的地板是安全隱患。"},{"en":"I would hazard a guess that sales will increase.","zh-TW":"我冒昧猜測銷售額會增加。"}]', '{"noun":"hazard","adjective":"hazardous","verb":"hazard"}', NULL, 2, 3211, NULL),
(3212, 'hazardous', '/ˈhæzərdəs/', 'adjective', '{"zh-TW":["危險的；有害的"],"en":["risky; involving danger"]}', NULL, 'hazardous materials/waste/conditions', '[{"en":"Workers must wear protective gear when handling hazardous materials.","zh-TW":"工人處理危險物質時必須穿戴防護裝備。"},{"en":"Driving in fog is extremely hazardous.","zh-TW":"在霧中駕駛極其危險。"}]', '{"noun":"hazard","adjective":"hazardous"}', NULL, 3, 3212, NULL),
(3213, 'hazardous waste', '/ˈhæzərdəs weɪst/', 'noun', '{"zh-TW":["有害廢棄物"],"en":["waste that poses a risk to health or the environment"]}', NULL, 'dispose of hazardous waste / hazardous waste management', '[{"en":"Hazardous waste must be disposed of properly.","zh-TW":"有害廢棄物必須妥善處置。"},{"en":"The factory was fined for improper hazardous waste disposal.","zh-TW":"工廠因不當處置有害廢棄物而被罰款。"}]', NULL, NULL, 5, 3213, NULL),
(3214, 'head', '/hɛd/', 'noun', '{"zh-TW":["【主要意義-名詞】頭部","【次要意義-動詞】朝向某方向；率領；帶頭","【次要意義-名詞】首腦；領導人；負責人","【次要意義-動詞】（列表/組織）排在首位"],"en":["[primary - noun] the part of the body above the neck","[secondary - verb] to go in a particular direction; to lead or be in charge","[secondary - noun] the leader or top person in an organization","[secondary - verb] to be at the top of a list or group"]}', NULL, 'head a department / head for / head office / go to head / heads of agreement', '[{"en":"She heads the product development division at the headquarters.","zh-TW":"她主管總部的產品研發部門。"},{"en":"The delegation is heading for the conference center.","zh-TW":"代表團正前往會議中心。"},{"en":"Heads of agreement were signed before the full contract was drafted.","zh-TW":"在起草完整合約之前，雙方簽署了基本協議要點。"}]', '{"noun":"heading, headquarters","adjective":"head-on"}', '動詞 head = 「率領/主管」，head for = 「朝……方向前進」，head office = 「總公司」，heads of agreement = 「基本協議要點」（TOEIC 法律文章）均是常考用法。', 1, 3214, NULL),
(3215, 'head of department', '/hed əv dɪˈpɑːrtmənt/', 'noun', '{"zh-TW":["部門主管；部門首長"],"en":["the most senior person responsible for a particular department"]}', NULL, 'report to the head of department / act as head of department', '[{"en":"The head of department approved the new hiring request.","zh-TW":"部門主管批准了新的招聘申請。"},{"en":"She was appointed head of department after 10 years of service.","zh-TW":"她在服務10年後被任命為部門主管。"}]', NULL, NULL, 5, 3215, NULL),
(3216, 'headcount', '/ˈhedkaʊnt/', 'noun', '{"zh-TW":["人數；員工總數"],"en":["the total number of people employed"]}', NULL, 'reduce/increase headcount', '[{"en":"The company reduced its headcount by 10%.","zh-TW":"公司裁減了10%的員工。"},{"en":"Current headcount stands at 450 employees.","zh-TW":"目前員工總數為450人。"}]', '{"noun":"headcount"}', NULL, 3, 3216, NULL),
(3217, 'headcount reduction', '/ˈhedkaʊnt rɪˈdʌkʃən/', 'noun', '{"zh-TW":["裁員；人員削減"],"en":["a decrease in the number of employees, typically through layoffs or natural attrition"]}', NULL, 'implement a headcount reduction / headcount reduction plan', '[{"en":"The company announced a headcount reduction to cut costs amid declining revenue.","zh-TW":"公司宣布裁員以在收入下降的情況下削減成本。"},{"en":"Natural attrition was used to achieve the headcount reduction target.","zh-TW":"自然減員被用於實現裁員目標。"}]', '{"synonym":"workforce reduction","synonym2":"downsizing"}', NULL, 5, 3217, NULL),
(3218, 'headhunter', '/ˈhedˌhʌntər/', 'noun', '{"zh-TW":["獵頭；招聘顧問"],"en":["a recruiter who seeks out highly qualified candidates for senior roles"]}', NULL, 'work with a headhunter / executive headhunter / hired by a headhunter', '[{"en":"The board appointed a headhunter to find their new CEO.","zh-TW":"董事會委託獵頭公司尋找新任執行長。"},{"en":"A headhunter approached her with an opportunity at a rival firm.","zh-TW":"一位獵頭以競爭對手公司的機會接觸了她。"}]', '{"plural":"headhunters","alternative":"executive search consultant"}', NULL, 4, 3218, NULL),
(3219, 'headhunting', '/ˈhedhʌntɪŋ/', 'noun', '{"zh-TW":["獵頭；高層人才招募"],"en":["the practice of recruiting senior executives through direct approach"]}', NULL, 'hire through headhunting / headhunting firm', '[{"en":"The company engaged a headhunting firm to find a new CFO.","zh-TW":"公司聘用了獵頭公司尋找新任首席財務官。"},{"en":"Headhunting is typically used for senior and specialized roles.","zh-TW":"獵頭通常用於高級和專業職位。"}]', '{"verb":"headhunt","noun":"headhunter"}', NULL, 4, 3219, NULL),
(3220, 'headline', '/ˈhedlaɪn/', 'noun, verb', '{"zh-TW":["頭條新聞；標題"],"en":["the title of a newspaper article; to be the main performer"]}', NULL, 'make headlines / headline news', '[{"en":"The merger made headlines worldwide.","zh-TW":"這次合併成為全球頭條新聞。"},{"en":"A famous singer will headline the concert.","zh-TW":"一位著名歌手將領銜這場音樂會。"}]', '{"noun":"headline","verb":"headline"}', NULL, 3, 3220, NULL),
(3221, 'headquarters', '/ˈhedˌkwɔːrtərz/', 'noun', '{"zh-TW":["總部；總公司"],"en":["the main office of an organization"]}', NULL, 'company/corporate headquarters', '[{"en":"The company moved its headquarters to New York.","zh-TW":"該公司將總部遷至紐約。"},{"en":"All major decisions are made at headquarters.","zh-TW":"所有重大決策都在總部做出。"}]', '{"noun":"headquarters"}', NULL, 4, 3221, 131),
(3222, 'headquarters relocation', '/ˌhɛdˌkwɔːrtərz ˌriːləʊˈkeɪʃən/', 'noun', '{"zh-TW":["總部遷移"],"en":["the move of a company''s main office to a new location"]}', NULL, 'plan a headquarters relocation / headquarters relocation announcement', '[{"en":"The company announced a headquarters relocation to reduce costs.","zh-TW":"公司宣布了總部遷移以降低成本。"},{"en":"The headquarters relocation took six months to complete.","zh-TW":"總部遷移花了六個月完成。"}]', NULL, NULL, 5, 3222, NULL),
(3223, 'headroom', '/ˈhedrʊm/', 'noun', '{"zh-TW":["空間；回旋餘地"],"en":["the room available for further growth or flexibility within limits"]}', NULL, 'financial headroom / regulatory headroom / operating headroom', '[{"en":"The company has enough financial headroom to fund the expansion.","zh-TW":"公司有足夠的財務空間為擴張提供資金。"},{"en":"Headroom in the credit facility allows for seasonal cash needs.","zh-TW":"信貸額度的回旋餘地滿足了季節性現金需求。"}]', NULL, NULL, 3, 3223, NULL),
(3224, 'health', '/hɛlθ/', 'noun', '{"zh-TW":["健康"],"en":["the state of being well"]}', NULL, 'health insurance / public health', '[{"en":"The company provides health insurance.","zh-TW":"公司提供健康保險。"},{"en":"Public health is a top priority.","zh-TW":"公共衛生是首要之務。"}]', '{"noun":"health","adjective":"healthy","adverb":"healthily","adjective2":"unhealthy"}', NULL, 2, 3224, NULL),
(3225, 'health and safety', '/hɛlθ ænd ˈseɪfti/', 'noun', '{"zh-TW":["健康與安全；職業安全衛生"],"en":["regulations and practices protecting workers from harm"]}', NULL, 'health and safety policy / comply with health and safety', '[{"en":"All employees must follow the company''s health and safety policy.","zh-TW":"所有員工必須遵守公司的健康與安全政策。"},{"en":"Health and safety audits are conducted twice a year.","zh-TW":"健康與安全審核每年進行兩次。"}]', NULL, NULL, 5, 3225, NULL),
(3226, 'health insurance', '/hɛlθ ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["健康保險"],"en":["insurance covering medical costs for the insured and their dependents"]}', NULL, 'provide health insurance / health insurance plan / health insurance coverage', '[{"en":"The company provides comprehensive health insurance for all employees.","zh-TW":"公司為所有員工提供全面的健康保險。"},{"en":"Health insurance is one of the most valued employee benefits.","zh-TW":"健康保險是最受重視的員工福利之一。"}]', '{"adjective":"health-insured"}', NULL, 5, 3226, NULL),
(3227, 'health maintenance', '/hɛlθ ˈmeɪntənəns/', 'noun', '{"zh-TW":["健康維護"],"en":["regular practices to keep the body in good condition"]}', NULL, 'health maintenance program / health maintenance organization', '[{"en":"Health maintenance includes regular exercise and a balanced diet.","zh-TW":"健康維護包括定期運動和均衡飲食。"},{"en":"She enrolled in a health maintenance organization plan.","zh-TW":"她加入了健康維護組織計劃。"}]', NULL, NULL, 5, 3227, NULL),
(3228, 'hear', '/hɪr/', 'verb', '{"zh-TW":["聽到；聽說"],"en":["to perceive sound","to learn about"]}', NULL, 'hear from / glad to hear', '[{"en":"I look forward to hearing from you.","zh-TW":"我期待收到你的回覆。"},{"en":"I heard the news this morning.","zh-TW":"我今早聽到了這個消息。"}]', '{"verb":"hear","noun":"hearing"}', NULL, 1, 3228, NULL),
(3229, 'hearsay', '/ˈhɪərseɪ/', 'noun', '{"zh-TW":["傳聞；道聽塗說"],"en":["a statement made outside court offered as evidence of its content"]}', NULL, 'hearsay evidence / hearsay exception / hearsay rule', '[{"en":"Hearsay evidence is generally inadmissible in court proceedings.","zh-TW":"傳聞證據通常在法庭訴訟中不可採納。"},{"en":"The attorney objected to the testimony as hearsay.","zh-TW":"律師以傳聞為由反對該證詞。"}]', '{"adjective":"hearsay"}', NULL, 3, 3229, NULL),
(3230, 'heart', '/hɑːrt/', 'noun', '{"zh-TW":["心臟；核心"],"en":["the organ that pumps blood","the central part"]}', NULL, 'at heart / heart of the matter', '[{"en":"Let''s get to the heart of the matter.","zh-TW":"讓我們切入問題核心。"},{"en":"He is a salesman at heart.","zh-TW":"他骨子裡是個業務員。"}]', '{"noun":"heart","adjective":"heartfelt","adjective2":"heartless"}', NULL, 2, 3230, NULL),
(3231, 'heavy', '/ˈhɛvi/', 'adjective', '{"zh-TW":["重的；大量的"],"en":["having great weight","large in amount"]}', NULL, 'heavy traffic / heavy workload', '[{"en":"There is heavy traffic during rush hour.","zh-TW":"尖峰時段交通很擁擠。"},{"en":"She has a heavy workload this month.","zh-TW":"她這個月工作量很大。"}]', '{"adjective":"heavy","adverb":"heavily","noun":"heaviness"}', NULL, 2, 3231, NULL),
(3232, 'hedge', '/hedʒ/', 'noun, verb', '{"zh-TW":["樹籬","對沖；規避風險"],"en":["a fence of bushes","to protect against financial loss"]}', NULL, 'hedge fund / hedge against risk', '[{"en":"Investors use gold to hedge against inflation.","zh-TW":"投資者用黃金來對沖通脹風險。"},{"en":"The garden was surrounded by a tall hedge.","zh-TW":"花園被高高的樹籬圍繞。"}]', '{"noun":"hedge","verb":"hedge"}', NULL, 2, 3232, NULL),
(3233, 'hedge fund', '/hɛdʒ fʌnd/', 'noun', '{"zh-TW":["對沖基金"],"en":["an investment fund employing various strategies to earn returns"]}', NULL, 'hedge fund manager / hedge fund strategy / hedge fund returns', '[{"en":"The hedge fund delivered 20% returns last year.","zh-TW":"對沖基金去年實現了20%的回報。"},{"en":"Hedge funds often use leverage to amplify returns.","zh-TW":"對沖基金經常使用槓桿來放大回報。"}]', NULL, NULL, 4, 3233, NULL),
(3234, 'hedging', '/ˈhɛdʒɪŋ/', 'noun', '{"zh-TW":["避險；對沖"],"en":["using financial instruments to reduce risk of adverse price movements"]}', NULL, 'currency hedging / hedging strategy / natural hedging', '[{"en":"The airline used fuel hedging to manage cost uncertainty.","zh-TW":"航空公司使用燃料對沖來管理成本不確定性。"},{"en":"Hedging protects profits from unfavorable exchange rate moves.","zh-TW":"避險保護利潤免受不利匯率變動的影響。"}]', '{"verb":"hedge","adjective":"hedged"}', NULL, 3, 3234, NULL),
(3235, 'hedging instrument', '/ˈhedʒɪŋ ˈɪnstrʊmənt/', 'noun', '{"zh-TW":["對沖工具"],"en":["a financial product used to reduce risk from price movements"]}', NULL, 'use a hedging instrument / choose the right hedging instrument', '[{"en":"Interest rate swaps are commonly used as a hedging instrument.","zh-TW":"利率掉期通常被用作對沖工具。"},{"en":"The company selected appropriate hedging instruments for currency risk.","zh-TW":"公司為貨幣風險選擇了適當的對沖工具。"}]', NULL, NULL, 5, 3235, NULL),
(3236, 'hedging strategy', '/ˈhedʒɪŋ ˈstrætədʒi/', 'noun', '{"zh-TW":["對沖策略"],"en":["a plan to reduce financial risk through offsetting positions"]}', NULL, 'implement a hedging strategy / review the hedging strategy', '[{"en":"The treasury team adopted a hedging strategy to protect against oil price rises.","zh-TW":"財資團隊採用了對沖策略以防止油價上漲。"},{"en":"A well-designed hedging strategy reduces earnings volatility.","zh-TW":"設計良好的對沖策略降低了盈利波動性。"}]', NULL, NULL, 5, 3236, NULL),
(3237, 'hedonic', '/hɪˈdɒnɪk/', 'adjective', '{"zh-TW":["享樂的；與快樂相關的"],"en":["relating to pleasure or the science measuring quality of life"]}', NULL, 'hedonic pricing / hedonic well-being / hedonic value', '[{"en":"Hedonic pricing models estimate property values based on location and amenities.","zh-TW":"享樂定價模型根據地點和設施估算房產價值。"},{"en":"Economists use hedonic indices to adjust prices for quality improvements over time.","zh-TW":"經濟學家使用享樂指數來調整隨時間推移品質改善的價格。"}]', '{"noun":"hedonism","adverb":"hedonically"}', NULL, 3, 3237, NULL),
(3238, 'hefty', '/ˈhefti/', 'adjective', '{"zh-TW":["大量的；沉重的"],"en":["large and heavy; substantial in amount"]}', NULL, 'hefty fine/fee/price/sum', '[{"en":"The company was hit with a hefty fine for non-compliance.","zh-TW":"公司因不合規被處以巨額罰款。"},{"en":"They paid a hefty price for the acquisition.","zh-TW":"他們為這次收購付出了高昂的代價。"}]', '{"adjective":"hefty"}', NULL, 2, 3238, NULL),
(3239, 'hegemony', '/hɪˈdʒeməni/', 'noun', '{"zh-TW":["霸權；文化主導權"],"en":["leadership or dominance, especially of one country or social group over others"]}', NULL, 'cultural hegemony / political hegemony / challenge hegemony', '[{"en":"Gramsci''s concept of hegemony explains how dominant classes maintain power.","zh-TW":"葛蘭西的霸權概念解釋了統治階級如何維持權力。"},{"en":"The hegemony of English in global business raises concerns about linguistic diversity.","zh-TW":"英語在全球商業中的霸權地位引發了對語言多樣性的擔憂。"}]', '{"adjective":"hegemonic","noun":"hegemon"}', NULL, 3, 3239, NULL),
(3240, 'help', '/hɛlp/', 'verb', '{"zh-TW":["幫助；協助"],"en":["to give assistance"]}', NULL, 'help desk / can''t help', '[{"en":"How can I help you today?","zh-TW":"今天我能怎麼幫你？"},{"en":"Contact the help desk for support.","zh-TW":"如需支援請聯繫服務台。"}]', '{"verb":"help","noun":"help","adjective":"helpful","adjective2":"helpless","noun2":"helper"}', NULL, 1, 3240, NULL),
(3241, 'help desk', '/help desk/', 'noun', '{"zh-TW":["服務台；技術支援"],"en":["a team or system providing support to users facing problems"]}', NULL, 'contact the help desk / help desk ticket / help desk software', '[{"en":"Users submit tickets to the help desk for technical issues.","zh-TW":"用戶向服務台提交技術問題工單。"},{"en":"The help desk resolved 95% of issues on first contact.","zh-TW":"服務台在第一次接觸時解決了95%的問題。"}]', NULL, NULL, 3, 3241, NULL),
(3242, 'helpdesk', '/ˈhɛlpdɛsk/', 'noun', '{"zh-TW":["客服台；技術支援"],"en":["a service providing assistance to users or customers"]}', NULL, 'contact the helpdesk / IT helpdesk', '[{"en":"Please contact the helpdesk if you experience any technical issues.","zh-TW":"如遇任何技術問題，請聯繫客服台。"},{"en":"The helpdesk resolved the issue in under ten minutes.","zh-TW":"客服台在十分鐘內解決了問題。"}]', NULL, NULL, 3, 3242, NULL),
(3243, 'hematologist', '/ˌhiːməˈtɒlədʒɪst/', 'noun', '{"zh-TW":["血液科醫師"],"en":["a doctor specializing in blood and blood-forming organs"]}', NULL, 'consult a hematologist / qualified hematologist / hematologist specialist', '[{"en":"The hematologist ordered further tests after abnormal blood results.","zh-TW":"血液科醫師在血液檢查結果異常後下令進一步測試。"},{"en":"Leukemia and other blood cancers are treated by hematologists.","zh-TW":"白血病和其他血癌由血液科醫師治療。"}]', NULL, NULL, 4, 3243, NULL),
(3244, 'hematology', '/ˌhiːməˈtɒlədʒi/', 'noun', '{"zh-TW":["血液學；血液科"],"en":["the branch of medicine dealing with blood disorders"]}', NULL, 'hematology test / hematology department', '[{"en":"The hematology department specializes in blood disorders.","zh-TW":"血液科專門研究血液疾病。"},{"en":"Blood tests in hematology can detect anemia and leukemia.","zh-TW":"血液科血液檢查可以檢測貧血和白血病。"}]', '{"noun":"hematologist","adjective":"hematological"}', NULL, 4, 3244, NULL),
(3245, 'heritage', '/ˈherɪtɪdʒ/', 'noun', '{"zh-TW":["遺產；傳統"],"en":["valued traditions and culture passed through generations","valued things passed down from previous generations"]}', '{"root":{"text":"herit","meaning":"inherit (繼承)"},"suffix":{"text":"-age","meaning":"state of (狀態)"},"logic":"被繼承下來的東西，即「遺產」。"}', 'cultural heritage / world heritage site', '[{"en":"We must protect our cultural heritage.","zh-TW":"我們必須保護我們的文化遺產。"},{"en":"The temple is a UNESCO World Heritage Site.","zh-TW":"這座寺廟是聯合國教科文組織世界遺產。"},{"en":"We must preserve our cultural heritage.","zh-TW":"我們必須保護我們的文化遺產。"}]', '{"noun":"heir","verb":"inherit"}', NULL, 3, 3245, NULL),
(3246, 'heritage site', '/''herɪtɪdʒ saɪt/', 'noun', '{"zh-TW":["文化遺址；世界遺産地"],"en":["a location with historical, cultural, or natural significance, often protected by law or recognized internationally"]}', NULL, 'visit a heritage site / UNESCO heritage site / protect a heritage site', '[{"en":"The ancient temple was designated a UNESCO heritage site in recognition of its cultural importance.","zh-TW":"這座古廟因其文化重要性被列為聯合國教科文組織世界遺産地。"},{"en":"Visitors are expected to respect heritage site regulations to preserve them for future generations.","zh-TW":"遊客應遵守文化遺址的規定，為後代保護這些遺址。"}]', '{"noun":"heritage"}', NULL, 5, 3246, NULL),
(3247, 'hesitate', '/ˈhezɪteɪt/', 'verb', '{"zh-TW":["猶豫；遲疑"],"en":["to pause before saying or doing something"]}', NULL, 'hesitate to do / without hesitation', '[{"en":"Don''t hesitate to contact us if you need help.","zh-TW":"如果需要幫助，請不要猶豫與我們聯繫。"},{"en":"She hesitated before answering the question.","zh-TW":"她在回答問題前猶豫了一下。"}]', '{"noun":"hesitation","verb":"hesitate","adjective":"hesitant","adverb":"hesitantly"}', NULL, 3, 3247, NULL),
(3248, 'heterogeneity', '/ˌhetərəʊdʒɪˈniːɪti/', 'noun', '{"zh-TW":["異質性；多樣性"],"en":["the quality of being diverse and not comparable in kind"]}', NULL, 'population heterogeneity / heterogeneity in responses / manage heterogeneity', '[{"en":"The study accounts for heterogeneity across different age groups.","zh-TW":"研究考慮到不同年齡組之間的異質性。"},{"en":"Heterogeneity in the workforce can be a source of creative problem-solving.","zh-TW":"勞動力的異質性可以成為創造性問題解決的來源。"}]', '{"adjective":"heterogeneous","adverb":"heterogeneously"}', NULL, 5, 3248, NULL),
(3249, 'heuristic', '/hjʊˈrɪstɪk/', 'noun', '{"zh-TW":["啟發法；經驗法則"],"en":["a practical problem-solving approach that is not guaranteed to be optimal"]}', NULL, 'heuristic approach / apply a heuristic / heuristic method', '[{"en":"A simple heuristic helps practitioners make quick decisions.","zh-TW":"簡單的啟發法幫助從業者快速做出決策。"},{"en":"The algorithm uses a heuristic to reduce computation time.","zh-TW":"該算法使用啟發法來減少計算時間。"}]', '{"adjective":"heuristic","adverb":"heuristically"}', NULL, 3, 3249, NULL);
