(3251, 'hide', '/haɪd/', 'verb', '{"zh-TW":["隱藏；躲藏"],"en":["to put out of sight","to keep secret"]}', NULL, 'hide information / hidden cost', '[{"en":"There are hidden costs in this contract.","zh-TW":"這份合約有隱藏成本。"},{"en":"Don''t hide mistakes from your manager.","zh-TW":"別對主管隱瞞錯誤。"}]', '{"verb":"hide","adjective":"hidden"}', NULL, 1, 3251, NULL),
