(3255, 'high tea', '/haɪ tiː/', 'noun', '{"zh-TW":["英式下午茶"],"en":["a British meal taken in the afternoon with tea and snacks"]}', NULL, 'enjoy high tea / traditional high tea', '[{"en":"They enjoyed high tea at a luxury hotel.","zh-TW":"他們在豪華飯店享用了英式下午茶。"},{"en":"High tea typically includes finger sandwiches and scones.","zh-TW":"英式下午茶通常包括小三明治和司康。"}]', NULL, NULL, 3, 3255, NULL),
