(3262, 'highbrow', '/ˈhaɪbraʊ/', 'adjective', '{"zh-TW":["高雅的；高智識的"],"en":["requiring or having an advanced level of knowledge or taste"]}', NULL, 'highbrow culture / highbrow audience / highbrow programming', '[{"en":"The documentary appeals to a highbrow audience interested in philosophy.","zh-TW":"這部紀錄片吸引了對哲學感興趣的高智識受眾。"},{"en":"Highbrow literary fiction often achieves critical acclaim rather than commercial success.","zh-TW":"高雅的文學小說通常獲得評論界讚譽而非商業成功。"}]', '{"antonym":"lowbrow","noun":"highbrow"}', NULL, 3, 3262, NULL),
