(3267, 'hire', '/ˈhaɪər/', 'verb, noun', '{"zh-TW":["僱用；租用","僱用"],"en":["to employ someone or rent something","the act of employing"]}', NULL, 'hire an employee / for hire', '[{"en":"We hired a consultant to review the plan.","zh-TW":"我們聘請了一位顧問來審查計劃。"},{"en":"The company plans to hire 50 new staff.","zh-TW":"公司計劃招聘50名新員工。"}]', '{"noun":"hire, hiring","verb":"hire"}', NULL, 1, 3267, NULL),
(3268, 'hire on a contract', '/haɪər ɒn ə ˈkɒntrækt/', 'verb', '{"zh-TW":["以合約方式聘用"],"en":["to employ someone on a fixed-term or project-based basis rather than permanently"]}', NULL, 'hire on a contract basis / contract-based hiring', '[{"en":"The company hired 20 specialists on a contract basis for the rollout.","zh-TW":"公司以合約方式聘用了20名專家負責推出工作。"},{"en":"Hiring on a contract is more flexible but may increase training costs.","zh-TW":"以合約方式聘用更具靈活性但可能增加培訓成本。"}]', NULL, NULL, 5, 3268, NULL),
