(3272, 'hold', '/hoʊld/', 'verb, noun', '{"zh-TW":["持有；握住；舉行","控制；影響力"],"en":["to have or keep in one''s hand; to organize an event","control or influence"]}', NULL, 'hold a meeting / hold responsible / take hold', '[{"en":"The conference will be held next Monday.","zh-TW":"會議將於下週一舉行。"},{"en":"Please hold the line while I transfer your call.","zh-TW":"請稍等，我為您轉接電話。"}]', '{"noun":"hold, holder, holding","verb":"hold"}', NULL, 1, 3272, NULL),
