(3276, 'hole', '/hoʊl/', 'noun', '{"zh-TW":["洞；漏洞"],"en":["an opening or gap"]}', NULL, 'loophole / fill a hole', '[{"en":"We found a hole in their argument.","zh-TW":"我們在他們的論點中發現了漏洞。"},{"en":"We need to fill the hole in our team.","zh-TW":"我們需要填補團隊的空缺。"}]', '{"noun":"hole","noun2":"loophole"}', NULL, 1, 3276, NULL),
(3277, 'holiday', '/ˈhɒlɪdeɪ/', 'noun', '{"zh-TW":["假日；假期"],"en":["a day off from work","a vacation"]}', NULL, 'public holiday / holiday season', '[{"en":"Monday is a public holiday.","zh-TW":"週一是公眾假期。"},{"en":"Sales peak during the holiday season.","zh-TW":"假期期間銷售達到高峰。"}]', '{"noun":"holiday"}', NULL, 3, 3277, NULL),
(3278, 'holistic', '/hoʊˈlɪstɪk/', 'adjective', '{"zh-TW":["整體的；全面的"],"en":["considering the whole rather than just parts"]}', NULL, 'holistic approach/view/strategy', '[{"en":"We need a holistic approach to problem-solving.","zh-TW":"我們需要一個整體性的問題解決方法。"},{"en":"The company takes a holistic view of employee wellness.","zh-TW":"公司對員工健康採取全面觀點。"}]', '{"adjective":"holistic","adverb":"holistically"}', NULL, 3, 3278, NULL),
