(3280, 'home', '/hoʊm/', 'noun', '{"zh-TW":["家；住所"],"en":["the place where one lives"]}', NULL, 'work from home / home page', '[{"en":"Many employees work from home now.","zh-TW":"現在很多員工在家工作。"},{"en":"Visit our home page for details.","zh-TW":"請造訪我們的首頁了解詳情。"}]', '{"noun":"home","adjective":"homely","noun2":"homeland","noun3":"homepage"}', NULL, 1, 3280, NULL),
(3281, 'home equity loan', '/''həʊm ˌekwɪti ləʊn/', 'noun', '{"zh-TW":["房屋淨值貸款"],"en":["a loan in which a homeowner borrows against the equity of their home"]}', NULL, 'apply for a home equity loan / use a home equity loan / home equity loan rate', '[{"en":"She used a home equity loan to fund her children''s university education.","zh-TW":"她使用房屋淨值貸款資助她孩子的大學教育。"},{"en":"A home equity loan typically offers lower interest rates than personal loans.","zh-TW":"房屋淨值貸款通常提供比個人貸款更低的利率。"}]', NULL, NULL, 5, 3281, NULL),
(3282, 'home inspection', '/''həʊm ɪnˈspekʃən/', 'noun', '{"zh-TW":["房屋檢查；房屋驗查"],"en":["a thorough examination of a property''s condition conducted before purchase"]}', NULL, 'schedule a home inspection / home inspection report / professional home inspection', '[{"en":"She hired an inspector to conduct a home inspection before making an offer.","zh-TW":"她在出價前聘請了一位檢查員進行房屋檢查。"},{"en":"The home inspection revealed a leak in the roof that required immediate repair.","zh-TW":"房屋檢查發現屋頂有漏水需要立即修復。"}]', NULL, NULL, 5, 3282, NULL),
(3283, 'home renovation loan', '/''həʊm ˌrenəˌveɪʃən ləʊn/', 'noun', '{"zh-TW":["房屋裝修貸款；改建貸款"],"en":["a type of loan specifically for financing home improvement projects"]}', NULL, 'apply for a home renovation loan / secure a home renovation loan', '[{"en":"She applied for a home renovation loan to fund the kitchen and bathroom upgrades.","zh-TW":"她申請了一筆房屋裝修貸款，用於廚房和浴室改造。"},{"en":"A home renovation loan can increase the value of a property significantly.","zh-TW":"房屋裝修貸款可以顯著提高房產的價值。"}]', NULL, NULL, 5, 3283, NULL),
(3284, 'homebuyer', '/''həʊmˌbaɪər/', 'noun', '{"zh-TW":["購房者；置業者"],"en":["a person who is in the process of buying or who has bought a home"]}', NULL, 'first-time homebuyer / homebuyer incentive / support homebuyers', '[{"en":"The government introduced a grant to help first-time homebuyers enter the market.","zh-TW":"政府推出了補助金，幫助首次購房者進入市場。"},{"en":"Homebuyers should compare mortgage rates from multiple lenders before choosing.","zh-TW":"購房者在選擇之前應比較多家貸款機構的按揭利率。"}]', NULL, NULL, 3, 3284, NULL),
(3285, 'homeowner', '/''həʊmˌəʊnər/', 'noun', '{"zh-TW":["房屋擁有者；屋主"],"en":["a person who owns the home in which they live"]}', NULL, 'first-time homeowner / proud homeowner / homeowner responsibilities', '[{"en":"First-time homeowners are eligible for a special tax deduction.","zh-TW":"首次置業的屋主有資格獲得特別稅收減免。"},{"en":"Homeowners insurance protects against damage to the property and liability claims.","zh-TW":"屋主保險保障房產損壞和責任索賠。"}]', '{"noun":"homeownership"}', NULL, 3, 3285, NULL),
(3286, 'homeowners association', '/''həʊmˌəʊnərz əˌsəʊsiˌeɪʃən/', 'noun', '{"zh-TW":["住宅業主委員會；業主協會"],"en":["an organization that manages a residential community and enforces rules for properties within it"]}', NULL, 'join a homeowners association / homeowners association fee / homeowners association rule', '[{"en":"The homeowners association requires all residents to maintain their lawns neatly.","zh-TW":"住宅業主委員會要求所有居民保持草坪整潔。"},{"en":"Monthly fees paid to the homeowners association cover maintenance of shared amenities.","zh-TW":"每月支付給業主協會的費用涵蓋共用設施的維護。"}]', NULL, NULL, 5, 3286, NULL),
(3287, 'homeownership', '/''həʊmˌəʊnərˌʃɪp/', 'noun', '{"zh-TW":["房屋所有權；自有住房"],"en":["the condition of owning one''s home rather than renting it"]}', NULL, 'achieve homeownership / homeownership rate / path to homeownership', '[{"en":"Homeownership remains the goal of many young people despite rising property prices.","zh-TW":"儘管房價上漲，房屋所有權仍然是許多年輕人的目標。"},{"en":"Government programs exist to help first-time buyers achieve homeownership.","zh-TW":"政府計劃的存在旨在幫助首次購房者實現房屋所有權。"}]', '{"noun":"homeowner"}', NULL, 5, 3287, NULL),
(3288, 'homestay', '/''həʊmsteɪ/', 'noun', '{"zh-TW":["寄宿家庭；家庭式住宿"],"en":["a form of travel where a visitor lives with a local family"]}', NULL, 'arrange a homestay / homestay family / language homestay', '[{"en":"The language school arranged a homestay to help students practice daily conversation.","zh-TW":"語言學校安排了寄宿家庭，幫助學生練習日常對話。"},{"en":"Living in a homestay gave her a deeper understanding of the local culture.","zh-TW":"住在寄宿家庭讓她對當地文化有了更深入的了解。"}]', NULL, NULL, 3, 3288, NULL),
(3289, 'homework', '/ˈhoʊmwɜːrk/', 'noun', '{"zh-TW":["家庭作業"],"en":["schoolwork done at home"]}', NULL, 'do homework / homework assignment', '[{"en":"Have you finished your homework?","zh-TW":"你做完作業了嗎？"},{"en":"The teacher assigned a lot of homework.","zh-TW":"老師佈置了很多作業。"}]', NULL, NULL, 3, 3289, NULL),
(3290, 'homework assignment', '/''həʊmwɜːrk əˌsaɪnmənt/', 'noun', '{"zh-TW":["家庭作業；課外作業"],"en":["schoolwork that students are assigned to complete outside of class"]}', NULL, 'complete a homework assignment / submit homework assignment / late homework assignment', '[{"en":"She completed her homework assignment despite a busy schedule that evening.","zh-TW":"儘管那天晚上時間緊張，她還是完成了家庭作業。"},{"en":"The teacher allows students to submit homework assignments online.","zh-TW":"教師允許學生在線提交家庭作業。"}]', NULL, NULL, 5, 3290, NULL),
(3291, 'homogeneity', '/ˌhɒməˈdʒiːnɪti/', 'noun', '{"zh-TW":["同質性；均一性"],"en":["the quality of being all the same or all of the same kind"]}', NULL, 'cultural homogeneity / homogeneity of data / lack of homogeneity', '[{"en":"Cultural homogeneity can reduce creativity and innovation within organizations.","zh-TW":"文化同質性可能會降低組織內部的創造力和創新力。"},{"en":"Statistical tests check data for homogeneity before applying parametric methods.","zh-TW":"在應用參數方法之前，統計測試會檢查數據的同質性。"}]', '{"adjective":"homogeneous","adverb":"homogeneously"}', NULL, 4, 3291, NULL),
(3292, 'honeymoon destination', '/''hʌnimuːn ˌdestɪˈneɪʃən/', 'noun', '{"zh-TW":["蜜月目的地；蜜月旅行地"],"en":["a location chosen by newlyweds for their post-wedding trip"]}', NULL, 'choose a honeymoon destination / dream honeymoon destination / popular honeymoon destination', '[{"en":"The Maldives remains one of the most popular honeymoon destinations in the world.","zh-TW":"馬爾地夫仍然是世界上最受歡迎的蜜月目的地之一。"},{"en":"They chose a mountain resort as their honeymoon destination for its peaceful setting.","zh-TW":"他們選擇了一個山地度假村作為蜜月目的地，因為其寧靜的環境。"}]', NULL, NULL, 5, 3292, NULL),
(3293, 'honor', '/ˈɑːnər/', 'noun, verb', '{"zh-TW":["榮譽；尊敬","給予榮譽"],"en":["great respect or distinction","to show respect or fulfill an obligation"]}', NULL, 'in honor of / honor a commitment', '[{"en":"It is an honor to receive this award.","zh-TW":"獲得這個獎項是一種榮譽。"},{"en":"The company honored its warranty obligations.","zh-TW":"公司履行了保固義務。"}]', '{"noun":"honor","adjective":"honorable","verb":"honor"}', NULL, 2, 3293, NULL),
(3294, 'honors degree', '/''ɒnərz dɪˌɡriː/', 'noun', '{"zh-TW":["榮譽學位；優等學位"],"en":["an undergraduate university qualification showing that the graduate achieved a high academic standard"]}', NULL, 'earn an honors degree / receive an honors degree / study for an honors degree', '[{"en":"She graduated with an honors degree in biochemistry from Oxford University.","zh-TW":"她以生物化學榮譽學位從牛津大學畢業。"},{"en":"An honors degree often requires a research project or thesis in the final year.","zh-TW":"榮譽學位通常在最後一年需要研究項目或論文。"}]', NULL, NULL, 5, 3294, NULL),
(3295, 'hope', '/hoʊp/', 'verb', '{"zh-TW":["希望"],"en":["to want something to happen"]}', NULL, 'hope for / in the hope of', '[{"en":"I hope this helps.","zh-TW":"希望這能有幫助。"},{"en":"We submitted in the hope of winning.","zh-TW":"我們提交申請希望能贏。"}]', '{"verb":"hope","noun":"hope","adjective":"hopeful","adjective2":"hopeless"}', NULL, 1, 3295, NULL),
(3296, 'horizontal', '/ˌhɔːrɪˈzɑːntl/', 'adjective', '{"zh-TW":["水平的；橫向的"],"en":["parallel to the ground; at the same level in a hierarchy"]}', NULL, 'horizontal integration / horizontal expansion', '[{"en":"The company pursued horizontal integration by acquiring competitors.","zh-TW":"公司通過收購競爭對手進行橫向整合。"},{"en":"Communication flows horizontally across departments.","zh-TW":"溝通在部門之間橫向流動。"}]', '{"noun":"horizon","adjective":"horizontal","adverb":"horizontally"}', NULL, 4, 3296, NULL),
(3297, 'horizontal integration', '/ˌhɒrɪˈzɒntəl ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["橫向整合"],"en":["merging with or acquiring competitors at the same level of production"]}', NULL, 'pursue horizontal integration / horizontal integration strategy', '[{"en":"The acquisition represented horizontal integration in the retail sector.","zh-TW":"此次收購代表了零售業的橫向整合。"},{"en":"Horizontal integration increases market share but may trigger antitrust reviews.","zh-TW":"橫向整合增加了市場份額，但可能觸發反壟斷審查。"}]', NULL, NULL, 5, 3297, NULL),
(3298, 'horizontal merger', '/ˌhɒrɪˈzɒntəl ˈmɜːrdʒər/', 'noun', '{"zh-TW":["橫向合併"],"en":["a merger between two companies operating in the same industry at the same level"]}', NULL, 'complete a horizontal merger / horizontal merger review', '[{"en":"The horizontal merger created the country''s largest retail chain.","zh-TW":"橫向合併創造了該國最大的零售連鎖。"},{"en":"Regulators scrutinize horizontal mergers for anti-competitive effects.","zh-TW":"監管機構對橫向合併進行反競爭效果審查。"}]', '{"opposite":"vertical merger"}', NULL, 5, 3298, NULL),
(3299, 'horse', '/hɔːrs/', 'noun', '{"zh-TW":["馬"],"en":["a large animal used for riding"]}', NULL, 'horsepower / dark horse', '[{"en":"The engine has 300 horsepower.","zh-TW":"這引擎有300匹馬力。"},{"en":"She is the dark horse in this competition.","zh-TW":"她是這場競爭中的黑馬。"}]', '{"noun":"horse","noun2":"horsepower"}', NULL, 2, 3299, NULL);
