(3300, 'hospital', '/ˈhɒspɪtəl/', 'noun', '{"zh-TW":["醫院"],"en":["a place where sick people are treated"]}', NULL, 'go to hospital / hospital bed', '[{"en":"He was taken to hospital after the accident.","zh-TW":"事故後他被送去醫院。"},{"en":"The new hospital opened last month.","zh-TW":"新醫院上個月開幕了。"}]', '{"noun":"hospital","noun2":"hospitality","verb":"hospitalize"}', NULL, 3, 3300, NULL),
(3301, 'hospitality', '/ˌhɑːspɪˈtæləti/', 'noun', '{"zh-TW":["好客；款待；餐旅業"],"en":["friendly and generous treatment of guests; the hotel industry"]}', NULL, 'hospitality industry / show hospitality', '[{"en":"She works in the hospitality industry.","zh-TW":"她在餐旅業工作。"},{"en":"We were impressed by their warm hospitality.","zh-TW":"他們熱情的款待讓我們印象深刻。"}]', '{"noun":"hospitality, host","adjective":"hospitable"}', NULL, 4, 3301, NULL),
(3302, 'hospitality industry', '/''hɒspɪˌtælɪti ˌɪndəstri/', 'noun', '{"zh-TW":["餐旅業；款待業"],"en":["the broad category of fields within the service industry that includes hotels, restaurants, and tourism"]}', NULL, 'work in the hospitality industry / hospitality industry trend / hospitality industry challenge', '[{"en":"The hospitality industry was one of the hardest hit sectors during the pandemic.","zh-TW":"餐旅業是疫情期間受打擊最嚴重的行業之一。"},{"en":"She built a successful career in the hospitality industry starting as a front desk clerk.","zh-TW":"她從前台接待員開始，在餐旅業建立了成功的職業生涯。"}]', '{"adjective":"hospitality"}', NULL, 5, 3302, NULL),
(3303, 'hospitalization', '/ˌhɒspɪtəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["住院治療"],"en":["the process of being admitted to and staying in a hospital"]}', NULL, 'require hospitalization / hospitalization cost', '[{"en":"The injury required two weeks of hospitalization.","zh-TW":"這次受傷需要兩週的住院治療。"},{"en":"Hospitalization costs are covered under this plan.","zh-TW":"住院費用在此計劃下獲得承保。"}]', '{"verb":"hospitalize","adjective":"hospitalized"}', NULL, 5, 3303, NULL),
(3304, 'host', '/hoʊst/', 'noun, verb', '{"zh-TW":["主人；主辦方","主辦；招待"],"en":["a person who receives or entertains guests","to organize an event"]}', NULL, 'host a conference/event/party', '[{"en":"Tokyo will host the next international summit.","zh-TW":"東京將主辦下一屆國際峰會。"},{"en":"She was a gracious host at the dinner party.","zh-TW":"她在晚宴上是位優雅的女主人。"}]', '{"noun":"host, hostess","verb":"host"}', NULL, 1, 3304, NULL),
(3305, 'hostel', '/''hɒstəl/', 'noun', '{"zh-TW":["青年旅舍；招待所"],"en":["a budget accommodation with dormitory beds shared among travelers"]}', NULL, 'stay in a hostel / youth hostel / book a hostel', '[{"en":"The hostel offered a clean dormitory bed for ten dollars a night.","zh-TW":"這家青年旅舍提供每晚十美元的乾淨宿舍床位。"},{"en":"We found a friendly hostel near the city center with a shared kitchen.","zh-TW":"我們在市中心附近找到一家有共用廚房的友善青年旅舍。"}]', NULL, NULL, 2, 3305, NULL),
(3306, 'hostel dormitory', '/''hɒstəl ˌdɔːrmɪtəri/', 'noun', '{"zh-TW":["青年旅館宿舍"],"en":["a shared sleeping room in a hostel, typically with bunk beds and multiple occupants"]}', NULL, 'stay in a hostel dormitory / book a hostel dormitory bed / mixed hostel dormitory', '[{"en":"Staying in a hostel dormitory is an affordable way to meet fellow travelers.","zh-TW":"住在青年旅館宿舍是以低成本結識旅伴的好方法。"},{"en":"The hostel dormitory had six bunk beds and a shared bathroom.","zh-TW":"青年旅館宿舍有六張雙層床和共用浴室。"}]', '{"noun":"dormitory"}', NULL, 5, 3306, NULL),
(3307, 'hostile', '/ˈhɑːstl/', 'adjective', '{"zh-TW":["敵對的；不友善的"],"en":["unfriendly; showing opposition"]}', NULL, 'hostile environment / hostile takeover', '[{"en":"The company faced a hostile takeover bid.","zh-TW":"該公司面臨了敵意收購。"},{"en":"The audience was openly hostile to the speaker.","zh-TW":"觀眾對演講者公開表示敵意。"}]', '{"noun":"hostility","adjective":"hostile"}', NULL, 3, 3307, NULL),
(3308, 'hostile takeover', '/ˈhɒstaɪl ˈteɪkoʊvər/', 'noun', '{"zh-TW":["惡意收購；敵意收購"],"en":["an acquisition made against the wishes of the target company management"]}', NULL, 'launch a hostile takeover / defend against a hostile takeover', '[{"en":"The board adopted a poison pill to deter a hostile takeover.","zh-TW":"董事會採用了毒丸策略阻止惡意收購。"},{"en":"A hostile takeover bid was made at a 30% premium to the share price.","zh-TW":"以高於股價30%的溢價發出了惡意收購要約。"}]', NULL, NULL, 5, 3308, NULL),
(3309, 'hot', '/hɒt/', 'adjective', '{"zh-TW":["熱的；熱門的"],"en":["having high temperature","very popular"]}', NULL, 'hot topic / hot market', '[{"en":"AI is a hot topic right now.","zh-TW":"人工智慧現在是熱門話題。"},{"en":"The real estate market is very hot.","zh-TW":"房地產市場非常火熱。"}]', '{"adjective":"hot","noun":"heat","verb":"heat"}', NULL, 1, 3309, NULL),
(3310, 'hot spring', '/''hɒt sprɪŋ/', 'noun', '{"zh-TW":["溫泉"],"en":["a spring of naturally warm or hot water, often used for bathing and relaxation"]}', NULL, 'soak in a hot spring / natural hot spring / hot spring resort', '[{"en":"The mountain town was famous for its therapeutic natural hot springs.","zh-TW":"這個山間小鎮以其有療效的天然溫泉聞名。"},{"en":"After the long hike, she relaxed in the hotel''s outdoor hot spring.","zh-TW":"長途徒步後，她在飯店的戶外溫泉中放鬆身心。"}]', NULL, NULL, 4, 3310, NULL),
(3311, 'hotel', '/hoʊˈtɛl/', 'noun', '{"zh-TW":["旅館；飯店"],"en":["a building providing accommodation for travelers"]}', NULL, 'hotel reservation / hotel chain', '[{"en":"I made a hotel reservation for the trip.","zh-TW":"我為出差預訂了飯店。"},{"en":"They manage a hotel chain.","zh-TW":"他們經營一家連鎖飯店。"}]', '{"noun":"hotel","noun2":"hotelier"}', NULL, 2, 3311, NULL),
(3312, 'hotel amenity', '/həʊˈtɛl əˈmiːnɪti/', 'noun', '{"zh-TW":["飯店設施"],"en":["a feature or facility available to hotel guests"]}', NULL, 'use hotel amenities / enjoy hotel amenities', '[{"en":"The hotel amenities include a rooftop pool and fitness center.","zh-TW":"飯店設施包括頂樓泳池和健身中心。"},{"en":"Take full advantage of the hotel amenities during your stay.","zh-TW":"住宿期間請充分利用飯店設施。"}]', NULL, NULL, 5, 3312, NULL),
(3313, 'hotel concierge', '/''həʊtel ˌkɒnsiˈerʒ/', 'noun', '{"zh-TW":["飯店禮賓員；飯店服務員"],"en":["a hotel employee who assists guests with special requests such as booking tickets and reservations"]}', NULL, 'ask the hotel concierge / helpful hotel concierge / hotel concierge service', '[{"en":"The hotel concierge helped arrange a private tour of the local vineyards.","zh-TW":"飯店禮賓員幫助安排了當地葡萄園的私人參觀。"},{"en":"A knowledgeable hotel concierge can transform an ordinary trip into an extraordinary one.","zh-TW":"知識淵博的飯店禮賓員可以將普通旅行變成非凡之旅。"}]', NULL, NULL, 5, 3313, NULL),
(3314, 'hotel loyalty program', '/''həʊtel ˌlɔɪəlti ˈprəʊɡræm/', 'noun', '{"zh-TW":["飯店忠誠度計畫"],"en":["a rewards scheme run by a hotel group that benefits frequent guests"]}', NULL, 'join a hotel loyalty program / hotel loyalty program points / hotel loyalty program benefits', '[{"en":"She earned enough points through the hotel loyalty program for a free night''s stay.","zh-TW":"她通過飯店忠誠度計畫積累了足夠的積分，換取了一晚免費住宿。"},{"en":"Hotel loyalty programs often offer members room upgrades and late checkout.","zh-TW":"飯店忠誠度計畫通常為會員提供房間升級和延遲退房服務。"}]', NULL, NULL, 5, 3314, NULL),
(3315, 'hotel reservation', '/həʊˈtɛl ˌrɛzərˈveɪʃən/', 'noun', '{"zh-TW":["飯店預訂"],"en":["a booking made in advance at a hotel"]}', NULL, 'make a hotel reservation / confirm a hotel reservation', '[{"en":"Please make your hotel reservation at least two weeks ahead.","zh-TW":"請至少提前兩週預訂飯店。"},{"en":"Her hotel reservation was lost due to a system error.","zh-TW":"她的飯店預訂因系統錯誤而丟失。"}]', NULL, NULL, 5, 3315, NULL),
(3316, 'hotline', '/ˈhɒtlaɪn/', 'noun', '{"zh-TW":["熱線電話；緊急聯絡電話"],"en":["a direct telephone line for urgent communication or support"]}', NULL, 'set up a hotline / call the hotline / ethics hotline', '[{"en":"The company set up a whistleblower hotline for reporting fraud.","zh-TW":"公司設立了舉報詐欺的吹哨人熱線。"},{"en":"Customer service representatives staff the hotline around the clock.","zh-TW":"客戶服務代表全天候支援熱線電話。"}]', NULL, NULL, 3, 3316, NULL),
(3317, 'hour', '/ˈaʊər/', 'noun', '{"zh-TW":["小時；時間"],"en":["a period of 60 minutes"]}', NULL, 'office hours / per hour', '[{"en":"Office hours are from 9 to 5.","zh-TW":"辦公時間是9點到5點。"},{"en":"The rate is $50 per hour.","zh-TW":"費率是每小時50美元。"}]', '{"noun":"hour","adjective":"hourly"}', NULL, 1, 3317, NULL),
(3318, 'house', '/haʊs/', 'noun', '{"zh-TW":["【主要意義-名詞】房子；住宅","【次要意義-動詞】容納；收藏；為……提供住所","【次要意義-名詞】議院；劇院；公司"],"en":["[primary - noun] a building for people to live in","[secondary - verb] to provide accommodation or storage space for something","[secondary - noun] a legislative assembly; a theater; a business firm"]}', NULL, 'house a collection / house equipment / the House of Representatives / in-house', '[{"en":"The new facility houses the company''s entire research and development team.","zh-TW":"新設施容納了公司整個研發團隊。"},{"en":"The museum houses over 10,000 works of art from around the world.","zh-TW":"博物館收藏了來自世界各地的逾萬件藝術品。"},{"en":"The server room houses all the critical data infrastructure.","zh-TW":"伺服器機房容納了所有關鍵的資料基礎設施。"}]', '{"noun":"housing, household","adjective":"in-house"}', '動詞 house（發音 /haʊz/）意為「容納/收藏」，常見於 TOEIC 描述設施、建築或機構功能的閱讀文章，考生易誤讀為名詞。', 2, 3318, NULL),
(3319, 'house appraisal', '/''haʊs əˌpreɪzəl/', 'noun', '{"zh-TW":["房屋評估；房產鑑價"],"en":["a professional assessment of a property''s market value"]}', NULL, 'request a house appraisal / house appraisal result / accurate house appraisal', '[{"en":"A house appraisal is required by most lenders before approving a mortgage.","zh-TW":"大多數貸款機構在批准抵押貸款之前需要進行房屋評估。"},{"en":"The house appraisal came in lower than expected, complicating the sale negotiations.","zh-TW":"房屋評估結果低於預期，使銷售談判更加複雜。"}]', '{"verb":"appraise","noun2":"appraiser"}', NULL, 5, 3319, NULL),
(3320, 'house hunting', '/''haʊs ˌhʌntɪŋ/', 'noun', '{"zh-TW":["找房子；看房"],"en":["the activity of searching for a house to buy or rent"]}', NULL, 'go house hunting / difficult house hunting / house hunting process', '[{"en":"After months of house hunting, they finally found the perfect family home.","zh-TW":"幾個月的找房後，他們終於找到了完美的家庭住宅。"},{"en":"House hunting in a competitive market requires patience and quick decision-making.","zh-TW":"在競爭激烈的市場上找房需要耐心和快速決策。"}]', NULL, NULL, 5, 3320, NULL),
(3321, 'house price index', '/''haʊs praɪs ˌɪndeks/', 'noun', '{"zh-TW":["房價指數"],"en":["a measure used to track changes in the prices of residential properties over time"]}', NULL, 'track the house price index / house price index growth / fall in house price index', '[{"en":"The house price index rose by fifteen percent over the past twelve months.","zh-TW":"房價指數在過去十二個月上漲了百分之十五。"},{"en":"Analysts use the house price index to predict trends in the housing market.","zh-TW":"分析師使用房價指數預測住房市場趨勢。"}]', NULL, NULL, 5, 3321, NULL),
(3322, 'house special', '/haʊs ˈspɛʃəl/', 'noun', '{"zh-TW":["本店特色菜"],"en":["a dish that the restaurant is known for"]}', NULL, 'order the house special / try the house special', '[{"en":"The house special is a grilled seafood platter.","zh-TW":"本店特色菜是烤海鮮拼盤。"},{"en":"I recommend trying the house special tonight.","zh-TW":"我建議今晚嘗試本店特色菜。"}]', NULL, NULL, 5, 3322, NULL),
(3323, 'household', '/ˈhaʊshoʊld/', 'noun, adjective', '{"zh-TW":["家庭；住戶","家庭的；家用的"],"en":["all the people living together in a house","relating to a house or family"]}', NULL, 'household income/expenses/chores', '[{"en":"The average household income has risen this year.","zh-TW":"今年平均家庭收入有所上升。"},{"en":"She manages all the household expenses.","zh-TW":"她管理所有的家庭開支。"}]', '{"noun":"household, householder"}', NULL, 3, 3323, NULL),
(3324, 'housekeeping', '/ˈhaʊskiːpɪŋ/', 'noun', '{"zh-TW":["客房清潔服務"],"en":["the cleaning and maintenance of hotel rooms"]}', NULL, 'housekeeping service / call housekeeping', '[{"en":"Please call housekeeping if you need extra towels.","zh-TW":"如需額外毛巾，請致電客房清潔服務。"},{"en":"Housekeeping cleans the room while guests are out.","zh-TW":"客房清潔人員在住客外出時打掃房間。"}]', '{"noun":"housekeeper","verb":"keep house"}', NULL, 4, 3324, NULL),
(3325, 'housing', '/ˈhaʊzɪŋ/', 'noun', '{"zh-TW":["住房；住宅"],"en":["buildings for people to live in"]}', NULL, 'affordable housing / housing market / housing development', '[{"en":"The city needs more affordable housing.","zh-TW":"這座城市需要更多經濟適用房。"},{"en":"Housing prices have increased dramatically.","zh-TW":"房價大幅上漲。"}]', '{"noun":"housing, house","verb":"house"}', NULL, 3, 3325, NULL),
(3326, 'housing affordability', '/''haʊzɪŋ əˌfɔːrdəˈbɪlɪti/', 'noun', '{"zh-TW":["住房可負擔性；房屋可及性"],"en":["the degree to which housing costs are manageable relative to income levels"]}', NULL, 'improve housing affordability / housing affordability crisis / measure housing affordability', '[{"en":"Housing affordability has worsened in major cities as incomes fail to keep pace with prices.","zh-TW":"由於收入無法跟上房價，主要城市的住房可負擔性已惡化。"},{"en":"The government introduced policies aimed at improving housing affordability for lower-income families.","zh-TW":"政府推出了旨在提高低收入家庭住房可負擔性的政策。"}]', NULL, NULL, 5, 3326, NULL),
(3327, 'housing estate', '/''haʊzɪŋ ɪˌsteɪt/', 'noun', '{"zh-TW":["住宅區；房屋開發項目"],"en":["a residential area developed at the same time, often with similar architecture and amenities"]}', NULL, 'live in a housing estate / new housing estate / gated housing estate', '[{"en":"The housing estate included two hundred homes, a park, and a community center.","zh-TW":"這個住宅區包含兩百棟房屋、一個公園和一個社區中心。"},{"en":"Many families prefer housing estates for their safe and community-oriented environment.","zh-TW":"許多家庭偏好住宅區，因為那裡安全且以社區為導向。"}]', NULL, NULL, 5, 3327, NULL),
(3328, 'housing market', '/''haʊzɪŋ ˌmɑːrkɪt/', 'noun', '{"zh-TW":["住房市場；房地產市場"],"en":["the market for buying, selling, and renting residential property"]}', NULL, 'hot housing market / cooling housing market / competitive housing market', '[{"en":"The housing market experienced record high prices during the low interest rate period.","zh-TW":"在低利率時期，住房市場經歷了創記錄的高房價。"},{"en":"First-time buyers struggle to enter the housing market due to high prices and deposits.","zh-TW":"首次購房者由於高房價和高首付而難以進入住房市場。"}]', NULL, NULL, 5, 3328, NULL),
(3329, 'housing subsidy', '/''haʊzɪŋ ˌsʌbsɪdi/', 'noun', '{"zh-TW":["住房補貼；房屋津貼"],"en":["financial assistance provided by the government to help people afford housing"]}', NULL, 'receive a housing subsidy / housing subsidy program / qualify for housing subsidy', '[{"en":"Low-income families may qualify for a housing subsidy to help cover rental costs.","zh-TW":"低收入家庭可能有資格獲得住房補貼，以幫助支付租金費用。"},{"en":"The government expanded the housing subsidy program to include more eligible households.","zh-TW":"政府擴大了住房補貼計劃，納入更多符合條件的家庭。"}]', NULL, NULL, 5, 3329, NULL),
(3330, 'HRIS', '/ˌeɪtʃ ɑːr aɪ ˈes/', 'noun', '{"zh-TW":["人力資源資訊系統"],"en":["human resources information system; software managing HR data and processes"]}', NULL, 'implement an HRIS / HRIS platform / HRIS integration', '[{"en":"The company upgraded its HRIS to automate payroll and leave tracking.","zh-TW":"公司升級了人力資源資訊系統以自動化薪資和假期追蹤。"},{"en":"HRIS data provides insights for workforce planning decisions.","zh-TW":"人力資源資訊系統數據為人力規劃決策提供見解。"}]', '{"full form":"human resources information system"}', NULL, 1, 3330, NULL),
(3331, 'hub', '/hʌb/', 'noun', '{"zh-TW":["中心；樞紐"],"en":["the central and most important part of a network"]}', NULL, 'transportation/business/innovation hub', '[{"en":"Singapore is a major business hub in Asia.","zh-TW":"新加坡是亞洲主要的商業樞紐。"},{"en":"The city is becoming a tech innovation hub.","zh-TW":"這座城市正在成為科技創新中心。"}]', '{"noun":"hub"}', NULL, 1, 3331, NULL),
(3332, 'hub airport', '/''hʌb ˌeərpɔːrt/', 'noun', '{"zh-TW":["樞紐機場；中轉機場"],"en":["a major airport that serves as a central transfer point for connecting flights and freight"]}', NULL, 'major hub airport / international hub airport / cargo hub airport', '[{"en":"Dubai International Airport serves as a major hub airport for flights between Asia and Europe.","zh-TW":"杜拜國際機場是連接亞洲和歐洲航班的主要樞紐機場。"},{"en":"Airlines route connecting flights through hub airports to maximize efficiency.","zh-TW":"航空公司通過樞紐機場安排轉機航班，以最大化效率。"}]', NULL, NULL, 4, 3332, NULL),
(3333, 'human', '/ˈhjuːmən/', 'adjective', '{"zh-TW":["人的；人類的"],"en":["relating to people"]}', NULL, 'human resources / human rights', '[{"en":"Contact the human resources department.","zh-TW":"請聯繫人力資源部門。"},{"en":"We respect human rights in all operations.","zh-TW":"我們在所有營運中尊重人權。"}]', '{"adjective":"human","noun":"human","noun2":"humanity","noun3":"humanitarian"}', NULL, 2, 3333, NULL),
(3334, 'human capital', '/ˈhjuːmən ˈkæpɪtl/', 'noun', '{"zh-TW":["人力資本"],"en":["the knowledge, skills, and experience of employees seen as assets"]}', NULL, 'invest in human capital / human capital development', '[{"en":"Investing in human capital development improves long-term productivity.","zh-TW":"投資人力資本發展提高了長期生產力。"},{"en":"The company views employee training as investment in human capital.","zh-TW":"公司將員工培訓視為對人力資本的投資。"}]', NULL, NULL, 5, 3334, NULL),
(3335, 'human resources', '/ˈhjuːmən rɪˈzɔːrsɪz/', 'noun', '{"zh-TW":["人力資源；人資部門"],"en":["the department responsible for managing employees"]}', NULL, 'human resources department / human resources manager', '[{"en":"Contact the human resources department for leave requests.","zh-TW":"如需請假，請聯繫人力資源部門。"},{"en":"The human resources team manages recruiting and training.","zh-TW":"人力資源團隊負責招募和培訓。"}]', '{"abbreviation":"HR"}', NULL, 5, 3335, NULL),
(3336, 'humanitarian', '/hjuːˌmænɪˈteriən/', 'adjective, noun', '{"zh-TW":["人道主義的","人道主義者"],"en":["concerned with reducing suffering","a person promoting human welfare"]}', NULL, 'humanitarian aid/crisis/organization', '[{"en":"The organization provides humanitarian aid to refugees.","zh-TW":"該組織為難民提供人道主義援助。"},{"en":"A humanitarian crisis is unfolding in the region.","zh-TW":"該地區正面臨人道主義危機。"}]', '{"noun":"humanitarian, humanity","adjective":"humanitarian, humane"}', NULL, 4, 3336, NULL),
(3337, 'humble', '/ˈhʌmbl/', 'adjective', '{"zh-TW":["謙虛的；卑微的"],"en":["having a modest view of one''s importance"]}', '{"root":{"text":"humil","meaning":"ground (地面)"},"logic":"源自拉丁語 humilis（低的），指不自視甚高。"}', 'humble beginnings / stay humble', '[{"en":"Despite his success, he remains humble.","zh-TW":"儘管成功，他仍然很謙虛。"},{"en":"She came from humble beginnings.","zh-TW":"她出身卑微。"}]', '{"noun":"humility","verb":"humble"}', NULL, 2, 3337, NULL),
(3338, 'humidity', '/hjuːˈmɪdəti/', 'noun', '{"zh-TW":["濕度"],"en":["the amount of water vapor in the air"]}', '{"root":{"text":"humid","meaning":"moist (潮濕)"},"suffix":{"text":"-ity","meaning":"state of (狀態)"},"logic":"潮濕的程度，即「濕度」。"}', 'high humidity / humidity level', '[{"en":"The humidity is very high in summer.","zh-TW":"夏天濕度很高。"},{"en":"High humidity makes it feel hotter.","zh-TW":"高濕度使體感更熱。"}]', '{"adjective":"humid","verb":"humidify","noun":"humidifier"}', NULL, 3, 3338, NULL),
(3339, 'hungry', '/ˈhʌŋɡri/', 'adjective', '{"zh-TW":["飢餓的；渴望的"],"en":["wanting food","eager for something"]}', NULL, 'power hungry / hungry for success', '[{"en":"The team is hungry for success.","zh-TW":"團隊渴望成功。"},{"en":"Shall we order lunch? I am hungry.","zh-TW":"我們點午餐吧？我餓了。"}]', '{"adjective":"hungry","noun":"hunger","adverb":"hungrily"}', NULL, 2, 3339, NULL),
(3340, 'hurdle', '/ˈhɜːrdl/', 'noun', '{"zh-TW":["障礙；難關"],"en":["a difficulty or obstacle to overcome"]}', NULL, 'overcome/clear a hurdle / regulatory hurdle', '[{"en":"The new regulation is a major hurdle for startups.","zh-TW":"新法規是新創公司的一大障礙。"},{"en":"We still have several hurdles to clear before launch.","zh-TW":"在推出之前我們還有幾個障礙需要克服。"}]', '{"noun":"hurdle","verb":"hurdle"}', NULL, 2, 3340, NULL),
(3341, 'hurdle rate', '/ˈhɜːrdəl reɪt/', 'noun', '{"zh-TW":["門檻利率；最低報酬率"],"en":["the minimum rate of return an investment must achieve before being approved"]}', NULL, 'set a hurdle rate / hurdle rate for capital projects', '[{"en":"Projects must exceed the 12% hurdle rate to receive board approval.","zh-TW":"項目必須超過12%的門檻利率才能獲得董事會批准。"},{"en":"The hurdle rate accounts for the cost of capital and risk premium.","zh-TW":"門檻利率考慮了資本成本和風險溢酬。"}]', NULL, NULL, 4, 3341, NULL),
(3342, 'hurricane', '/ˈhɜːrɪkeɪn/', 'noun', '{"zh-TW":["颶風"],"en":["a violent tropical storm with very strong winds"]}', '{"root":{"text":"hurricane","meaning":"god of storm (風暴之神)"},"logic":"源自加勒比原住民語言 hurakán（風暴之神）。"}', 'hurricane season / hurricane warning', '[{"en":"The hurricane caused billions of dollars in damage.","zh-TW":"颶風造成數十億美元的損害。"},{"en":"Residents evacuated before the hurricane hit.","zh-TW":"居民在颶風來襲前撤離。"}]', NULL, NULL, 3, 3342, NULL),
(3343, 'hurry', '/ˈhʌri/', 'verb', '{"zh-TW":["趕快；匆忙"],"en":["to move or do something quickly"]}', NULL, 'in a hurry / hurry up', '[{"en":"I am in a hurry to catch my flight.","zh-TW":"我趕著搭飛機。"},{"en":"We need to hurry to meet the deadline.","zh-TW":"我們得趕快以趕上截止日期。"}]', '{"verb":"hurry","noun":"hurry","adjective":"hurried","adverb":"hurriedly"}', NULL, 2, 3343, NULL),
(3344, 'husband', '/ˈhʌzbənd/', 'noun', '{"zh-TW":["【主要意義-名詞】丈夫","【次要意義-動詞】節約使用；精打細算地管理（資源）"],"en":["[primary - noun] a married man","[secondary - verb] to use something carefully and economically; to conserve resources"]}', NULL, 'husband resources / husband one''s strength / husband energy', '[{"en":"The company must husband its resources carefully during the economic downturn.","zh-TW":"在經濟衰退期間，公司必須謹慎地節約使用資源。"},{"en":"She husbanded her energy for the final push of the marathon.","zh-TW":"她節省體力以備馬拉松最後衝刺之用。"},{"en":"Good farmers husband the land to ensure long-term productivity.","zh-TW":"好的農夫會善加管理土地以確保長期生產力。"}]', '{"noun":"husbandry"}', '動詞 husband 與名詞「丈夫」毫無關聯，意為「節儉管理資源」，常見於 TOEIC 描述資源管理或商業策略的閱讀題。', 3, 3344, NULL),
(3345, 'hybrid financing', '/ˈhaɪbrɪd ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["混合融資"],"en":["a mix of debt and equity financing instruments"]}', NULL, 'use hybrid financing / hybrid financing structure / hybrid financing instrument', '[{"en":"Hybrid financing combines the benefits of debt and equity for the issuer.","zh-TW":"混合融資為發行人結合了債務和股權的優點。"},{"en":"Convertible bonds are a common form of hybrid financing.","zh-TW":"可轉換債券是混合融資的常見形式。"}]', NULL, NULL, 5, 3345, NULL),
(3346, 'hybrid model', '/ˈhaɪbrɪd ˈmɒdəl/', 'noun', '{"zh-TW":["混合模式"],"en":["a system combining features of two different approaches"]}', NULL, 'hybrid business model / hybrid work model / adopt a hybrid model', '[{"en":"Many companies adopted a hybrid work model after the pandemic.","zh-TW":"許多公司在疫情後採用了混合工作模式。"},{"en":"The hybrid model combines online instruction with in-person sessions.","zh-TW":"混合模式將線上教學與面對面課程相結合。"}]', NULL, NULL, 4, 3346, NULL),
(3347, 'hybrid work', '/ˈhaɪbrɪd wɜːrk/', 'noun', '{"zh-TW":["混合工作模式"],"en":["a model combining remote and in-office work"]}', NULL, 'hybrid work model / hybrid work policy / implement hybrid work', '[{"en":"The company adopted a hybrid work model of three days in office.","zh-TW":"公司採用了每週三天辦公室的混合工作模式。"},{"en":"Hybrid work arrangements offer flexibility while maintaining team cohesion.","zh-TW":"混合工作安排提供靈活性，同時保持團隊凝聚力。"}]', '{"adjective":"hybrid"}', NULL, 4, 3347, NULL),
(3348, 'hydration', '/''haɪˈdreɪʃən/', 'noun', '{"zh-TW":["補水；水分補充"],"en":["the process of providing or absorbing adequate water to maintain health and performance"]}', NULL, 'stay hydrated / proper hydration / hydration strategy', '[{"en":"Proper hydration is essential for athletic performance, especially in hot weather.","zh-TW":"適當補水對運動表現至關重要，尤其是在炎熱天氣。"},{"en":"Athletes should monitor their hydration levels before, during, and after exercise.","zh-TW":"運動員應在運動前、中、後監測水分補充水平。"}]', '{"verb":"hydrate","adjective":"hydrated"}', NULL, 3, 3348, NULL),
(3349, 'hydropower', '/ˈhaɪdrəʊpaʊər/', 'noun', '{"zh-TW":["水力發電；水電"],"en":["electricity generated using the flow of water"]}', NULL, 'generate hydropower / hydropower plant', '[{"en":"The country relies heavily on hydropower for its electricity.","zh-TW":"這個國家嚴重依賴水力發電。"},{"en":"Hydropower is a clean and renewable energy source.","zh-TW":"水力發電是清潔可再生能源。"}]', NULL, NULL, 4, 3349, NULL);